\title{Browser view wire format}
\begin{semanticmodule}
definition{
  name: viewWireLimits,
  parameters: [],
  result: Foundation.Codec.Cbor.V1.Primitive::CborLimits,
  body: (record Foundation.Codec.Cbor.V1.Primitive::CborLimits {maximumInput := 67108864, maximumOutput := 67108864, maximumBytes := 2097152, maximumText := 67108864, maximumArrayItems := 4096}),
  axioms: []
}

