    {name: value, type: Foundation.Codec.Cbor.V1.Primitive::CborValue},
    {name: cursor, type: Nat}
  ]
}

definition{
  name: viewWireWindow,
  parameters: [input : ViewWireInput, cursor : Nat],
  result: (Result Bytes Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (cursor <=? (prim length (project input bytes) : Nat))
    | Bool.false => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.BadCursor))
    | Bool.true => (match (prim slice (project input bytes) cursor (match ((prim subtract (prim length (project input bytes) : Nat) cursor : Nat) <=? 5)
        | Bool.false => 5
        | Bool.true => (prim subtract (prim length (project input bytes) : Nat) cursor : Nat)) : (Option Bytes))
      | Option.none => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.Truncated))
      | Option.some window => (ctor Result.ok [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] window))),
  axioms: []
}

definition{
  name: viewWireReadHeader,
  parameters: [input : ViewWireInput, cursor : Nat, major : Nat],
  result: (Result ViewWireHeader Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (viewWireWindow input cursor)
    | Result.error wireCause => (ctor Result.error [ViewWireHeader, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
    | Result.ok window => (match (Foundation.Codec.Cbor.V1.Primitive::cborReadHead (record Foundation.Codec::BoundedCursor {bytes := window, offset := 0, limit := (prim length window : Nat)}) (viewWireLimits) major)
      | Result.error wireCause => (ctor Result.error [ViewWireHeader, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
      | Result.ok header => (ctor Result.ok [ViewWireHeader, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWireHeader {count := (project header argument), cursor := (cursor + (project (project header cursor) offset))})))),
  axioms: [Quot.sound, propext]
}

definition{
  name: viewWireReadArray,
  parameters: [input : ViewWireInput, cursor : Nat, maximum : Nat],
  result: (Result ViewWireHeader Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (viewWireReadHeader input cursor 4)
    | Result.error wireCause => (ctor Result.error [ViewWireHeader, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
    | Result.ok header => (match ((project header count) <=? maximum)
      | Bool.false => (ctor Result.error [ViewWireHeader, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.ValueLimit))
      | Bool.true => (ctor Result.ok [ViewWireHeader, Foundation.Codec.Cbor.V1.Primitive::CborError] header))),
  axioms: [Quot.sound, propext]
}

definition{
  name: viewWireReadAtom,
  parameters: [input : ViewWireInput, cursor : Nat],
  result: (Result ViewWirePrimitive Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (viewWireWindow input cursor)
    | Result.error wireCause => (ctor Result.error [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
    | Result.ok window => (match (Foundation.Codec.Cbor.V1.Primitive::readCborPrimitive (record Foundation.Codec::BoundedCursor {bytes := window, offset := 0, limit := (prim length window : Nat)}) (record Foundation.Codec.Cbor.V1.Primitive::CborLimits {maximumInput := 67108864, maximumOutput := 67108864, maximumBytes := 0, maximumText := 67108864, maximumArrayItems := 4096}))
      | Result.error wireCause => (ctor Result.error [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
      | Result.ok decoded => (ctor Result.ok [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWirePrimitive {value := (project decoded value), cursor := (cursor + (project (project decoded cursor) offset))})))),
  axioms: [Classical.choice, Quot.sound, propext]
}

