    | Result.error wireCause => (ctor Result.error [ViewWireReadNat, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
    | Result.ok decoded => (match (project decoded value)
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Unsigned scalar => (ctor Result.ok [ViewWireReadNat, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWireReadNat {value := scalar, cursor := (project decoded cursor)}))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.ByteString scalar => (ctor Result.error [ViewWireReadNat, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.TextString scalar => (ctor Result.error [ViewWireReadNat, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Boolean scalar => (ctor Result.error [ViewWireReadNat, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Null => (ctor Result.error [ViewWireReadNat, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType)))),
  axioms: [Classical.choice, Quot.sound, propext]
}

