      | Foundation.Codec.Cbor.V1.Primitive::CborValue.ByteString scalar => (ctor Result.error [ViewWireReadBool, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.TextString scalar => (ctor Result.error [ViewWireReadBool, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Boolean scalar => (ctor Result.ok [ViewWireReadBool, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWireReadBool {value := scalar, cursor := (project decoded cursor)}))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Null => (ctor Result.error [ViewWireReadBool, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType)))),
