definition{
  name: viewWireReadString,
  parameters: [input : ViewWireInput, cursor : Nat, maximum : Nat, textMode : Bool],
  result: (Result ViewWirePrimitive Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (viewWireReadHeader input cursor (match textMode | Bool.false => 2 | Bool.true => 3))
    | Result.error wireCause => (ctor Result.error [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
    | Result.ok header => (match ((project header count) <=? maximum)
      | Bool.false => (ctor Result.error [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.ValueLimit))
      | Bool.true => (match (prim slice (project input bytes) (project header cursor) (project header count) : (Option Bytes))
        | Option.none => (ctor Result.error [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.Truncated))
        | Option.some payload => (match textMode
          | Bool.false => (ctor Result.ok [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWirePrimitive {value := (ctor Foundation.Codec.Cbor.V1.Primitive::CborValue.ByteString payload), cursor := ((project header cursor) + (project header count))}))
          | Bool.true => (match (prim utf8_decode payload : (Option String))
            | Option.none => (ctor Result.error [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.InvalidUtf8))
            | Option.some text => (ctor Result.ok [ViewWirePrimitive, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWirePrimitive {value := (ctor Foundation.Codec.Cbor.V1.Primitive::CborValue.TextString text), cursor := ((project header cursor) + (project header count))}))))))),
  axioms: [Classical.choice, Quot.sound, propext]
}

definition{
  name: readViewWireText,
  parameters: [input : ViewWireInput, cursor : Nat],
  result: (Result ViewWireReadText Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (viewWireReadString input cursor 67108864 true)
    | Result.error wireCause => (ctor Result.error [ViewWireReadText, Foundation.Codec.Cbor.V1.Primitive::CborError] wireCause)
    | Result.ok decoded => (match (project decoded value)
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Unsigned scalar => (ctor Result.error [ViewWireReadText, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.ByteString scalar => (ctor Result.error [ViewWireReadText, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.TextString scalar => (ctor Result.ok [ViewWireReadText, Foundation.Codec.Cbor.V1.Primitive::CborError] (record ViewWireReadText {value := scalar, cursor := (project decoded cursor)}))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Boolean scalar => (ctor Result.error [ViewWireReadText, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType))
      | Foundation.Codec.Cbor.V1.Primitive::CborValue.Null => (ctor Result.error [ViewWireReadText, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType)))),
