definition{
  name: viewWireAppend,
  parameters: [left : Bytes, right : Bytes],
  result: (Result Bytes Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (record ViewWireSizes {left := (prim length left : Nat), right := (prim length right : Nat)})
    | ViewWireSizes.mk leftSize rightSize => (match (leftSize <=? 67108864)
      | Bool.false => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.ValueLimit))
      | Bool.true => (match (rightSize <=? 67108864)
        | Bool.false => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.ValueLimit))
        | Bool.true => (match ((leftSize + rightSize) <=? 67108864)
          | Bool.false => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] (ctor Foundation.Codec.Cbor.V1.Primitive::CborError.ValueLimit))
          | Bool.true => (ctor Result.ok [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] (prim append left right : Bytes)))))),
  axioms: []
}

definition{
  name: viewWireJoin,
  parameters: [
    left : (Result Bytes Foundation.Codec.Cbor.V1.Primitive::CborError),
    right : (Result Bytes Foundation.Codec.Cbor.V1.Primitive::CborError)
  ],
  result: (Result Bytes Foundation.Codec.Cbor.V1.Primitive::CborError),
  body: (match (viewWireOutput left)
    | ViewWireOutput.mk prefix leftCause => (match leftCause
      | Option.some cause => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] cause)
      | Option.none => (match (viewWireOutput right)
        | ViewWireOutput.mk suffix rightCause => (match rightCause
          | Option.some cause => (ctor Result.error [Bytes, Foundation.Codec.Cbor.V1.Primitive::CborError] cause)
          | Option.none => (viewWireAppend prefix suffix))))),
  axioms: []
}

definition{
  name: viewWireErrorBytes,
  parameters: [cause : Foundation.Codec.Cbor.V1.Primitive::CborError],
  result: Bytes,
  body: (match cause
    | Foundation.Codec.Cbor.V1.Primitive::CborError.BadLimits => 0x83010100
    | Foundation.Codec.Cbor.V1.Primitive::CborError.BadCursor => 0x83010101
    | Foundation.Codec.Cbor.V1.Primitive::CborError.Truncated => 0x83010102
    | Foundation.Codec.Cbor.V1.Primitive::CborError.WrongType => 0x83010103
    | Foundation.Codec.Cbor.V1.Primitive::CborError.UnsupportedHead => 0x83010104
    | Foundation.Codec.Cbor.V1.Primitive::CborError.NonCanonical => 0x83010105
    | Foundation.Codec.Cbor.V1.Primitive::CborError.ValueLimit => 0x83010106
    | Foundation.Codec.Cbor.V1.Primitive::CborError.InvalidUtf8 => 0x83010107
    | Foundation.Codec.Cbor.V1.Primitive::CborError.TrailingInput => 0x83010108),
  axioms: []
}

